gr3(){return"\u10e3\u10d0\u10e0\u10d8\u10e1 \u10d7\u10e5\u10db\u10d0"},
grp(){return"\u10db\u10d4\u10d2\u10dd\u10d1\u10e0\u10d8\u10e1 \u10e5\u10dd\u10e0\u10ec\u10d8\u10da\u10d8"},
ro(a){return"\u10d9\u10d0\u10e0\u10d2\u10d8 \u10db\u10d4\u10d2\u10dd\u10d1\u10e0\u10d4\u10d1\u10d8 \u10e8\u10dd\u10e0\u10e1 \u10e5\u10dd\u10e0\u10ec\u10d8\u10dc\u10d3\u10d4\u10d1\u10d8\u10d0\u10dc. \u10db\u10d2\u10d6\u10d0\u10d5\u10e0\u10dd\u10d1\u10d0, \u10e1\u10d0\u10e1\u10e2\u10e3\u10db\u10e0\u10dd \u10d3\u10d0 \u10e1\u10d0\u10e9\u10e3\u10e5\u10d0\u10e0\u10d8 \u10ef\u10d0\u10db\u10e8\u10d8 "+a+" \u10ef\u10d3\u10d4\u10d1\u10d0."},
grq(){return"\u10ec\u10d0\u10e1\u10d5\u10da\u10d0 \u10d3\u10d0 \u10d6\u10d4\u10d8\u10db\u10d8"},
