lV(a){return"\u10e8\u10d4\u10dc\u10d8 \u10e1\u10d0\u10e7\u10d5\u10d0\u10e0\u10d4\u10da\u10d8 \u10ef\u10d2\u10e3\u10e4\u10d8 \u10e4\u10d4\u10e1\u10e2\u10d8\u10d5\u10d0\u10da\u10d6\u10d4 \u10e3\u10d9\u10e0\u10d0\u10d5\u10e1. \u10d1\u10d8\u10da\u10d4\u10d7\u10d8 \u10d3\u10d0 \u10db\u10d2\u10d6\u10d0\u10d5\u10e0\u10dd\u10d1\u10d0 "+a+" \u10ef\u10d3\u10d4\u10d1\u10d0."},
glX(){return"\u10d1\u10d8\u10da\u10d4\u10d7\u10d4\u10d1\u10d8\u10e1 \u10e7\u10d8\u10d3\u10d5\u10d0"},
glU(){return"\u10d0\u10db\u10ef\u10d4\u10e0\u10d0\u10d3 \u10d0\u10e0\u10d0"},
gir(){return"\u10e1\u10d0\u10e1\u10d9\u10dd\u10da\u10dd \u10d4\u10e5\u10e1\u10d9\u10e3\u10e0\u10e1\u10d8\u10d0"},
iq(a){return"\u10e8\u10d4\u10dc\u10d8 \u10e8\u10d5\u10d8\u10da\u10d8\u10e1 \u10d9\u10da\u10d0\u10e1\u10d8 \u10d4\u10e0\u10d7\u10d8 \u10d9\u10d5\u10d8\u10e0\u10d8\u10d7 \u10d4\u10e5\u10e1\u10d9\u10e3\u10e0\u10e1\u10d8\u10d0\u10d6\u10d4 \u10db\u10d8\u10d3\u10d8\u10e1. \u10d4\u10e1 "+a+" \u10ef\u10d3\u10d4\u10d1\u10d0."},
gis(){return"\u10d2\u10d0\u10d3\u10d0\u10ee\u10d3\u10d0"},
gip(){return"\u10e8\u10d5\u10d8\u10da\u10d8 \u10e1\u10d0\u10ee\u10da\u10e8\u10d8 \u10e0\u10e9\u10d4\u10d1\u10d0"},
