mD(a){return"\u10e8\u10d4\u10dc\u10e1 \u10e8\u10d5\u10d8\u10da\u10e1 \u10eb\u10d0\u10da\u10d8\u10d0\u10dc \u10e3\u10dc\u10d3\u10d0 \u10d0\u10ee\u10d0\u10da\u10d8 \u10d5\u10d4\u10da\u10dd\u10e1\u10d8\u10de\u10d4\u10d3\u10d8, \u10e0\u10dd\u10db\u10d4\u10da\u10d8\u10ea "+a+" \u10e6\u10d8\u10e0\u10e1."},
gmF(){return"\u10e7\u10d8\u10d3\u10d5\u10d0"},
gmA(){return"\u10d4\u10e0\u10d7\u10d0\u10d3 \u10d3\u10d0\u10d6\u10dd\u10d2\u10d5\u10d0: \u10dc\u10d0\u10ee\u10d4\u10d5\u10d0\u10e0\u10e1 \u10e8\u10d4\u10dc \u10d8\u10ee\u10d3\u10d8"},
gmC(){return"\u10d0\u10e0\u10d0"},
