grj(){return"\u10d5\u10d4\u10e2\u10d4\u10e0\u10d8\u10dc\u10d0\u10e0\u10d7\u10d0\u10dc"},
ri(a){return"\u10e8\u10d4\u10dc\u10d8 \u10eb\u10d0\u10e6\u10da\u10d8 \u10d0\u10e6\u10d0\u10e0 \u10ed\u10d0\u10db\u10e1 \u10d3\u10d0 \u10db\u10d9\u10e3\u10e0\u10dc\u10d0\u10da\u10dd\u10d1\u10d0 \u10e1\u10ed\u10d8\u10e0\u10d3\u10d4\u10d1\u10d0. \u10d2\u10d0\u10d3\u10d0\u10e1\u10d0\u10ee\u10d3\u10d4\u10da\u10d8: "+a+"."},
gqh(){return"\u10e1\u10d0\u10ee\u10e3\u10e0\u10d0\u10d5\u10d8 \u10df\u10dd\u10dc\u10d0\u10d5\u10e1"},
qg(a){return"\u10e5\u10d0\u10e0\u10d8\u10e8\u10ee\u10da\u10d8\u10e1 \u10e8\u10d4\u10db\u10d3\u10d4\u10d2 \u10e1\u10d0\u10ee\u10e3\u10e0\u10d0\u10d5\u10d8\u10d3\u10d0\u10dc \u10ec\u10d5\u10d8\u10db\u10d0 \u10e9\u10d0\u10db\u10dd\u10d3\u10d8\u10e1. \u10e8\u10d4\u10d9\u10d4\u10d7\u10d4\u10d1\u10d0 "+a+" \u10ef\u10d3\u10d4\u10d1\u10d0 \u2013 \u10e0\u10dd\u10d2\u10dd\u10e0\u10ea \u10e1\u10d0\u10ee\u10da\u10d8\u10e1 \u10db\u10e4\u10da\u10dd\u10d1\u10d4\u10da\u10d8, \u10e7\u10d5\u10d4\u10da\u10d0\u10e4\u10d4\u10e0\u10e1 \u10d7\u10d0\u10d5\u10d0\u10d3 \u10d8\u10ee\u10d3\u10d8."},
mi(a){return"\u10db\u10d4\u10db\u10d9\u10d5\u10d8\u10d3\u10e0\u10d4\u10dd\u10d1\u10d0: "+a},
gmh(){return"\u10e8\u10dd\u10e0\u10d4\u10e3\u10da\u10db\u10d0 \u10d3\u10d4\u10d8\u10d3\u10d0\u10db \u10ea\u10dd\u10e2\u10d0 \u10e4\u10e3\u10da\u10d8 \u10d3\u10d0\u10d2\u10d8\u10e2\u10dd\u10d5\u10d0. \u10e0\u10d0\u10e1 \u10e3\u10d6\u10d0\u10db?"},
gih(){return"\u201e\u10e1\u10d0\u10d8\u10d3\u10e3\u10db\u10da\u10dd \u10e0\u10e9\u10d4\u10d5\u10d0\u201c"},
ig(a){return"\u10dc\u10d0\u10ea\u10dc\u10dd\u10d1\u10d8 \u10d0\u10e6\u10e4\u10e0\u10d7\u10dd\u10d5\u10d0\u10dc\u10d4\u10d1\u10d8\u10d7 \u10e7\u10d5\u10d4\u10d1\u10d0 \u10d4\u10e0\u10d7 \u10de\u10da\u10d0\u10e2\u10e4\u10dd\u10e0\u10db\u10d0\u10d6\u10d4: \u10d7\u10d5\u10d4\u10e8\u10d8 10% \u10db\u10dd\u10d2\u10d4\u10d1\u10d0, \u10d2\u10d0\u10e0\u10d0\u10dc\u10e2\u10d8\u10e0\u10d4\u10d1\u10e3\u10da\u10d0\u10d3! \u10db\u10d8\u10dc\u10d8\u10db\u10d0\u10da\u10e3\u10e0\u10d8 \u10e8\u10d4\u10dc\u10d0\u10e2\u10d0\u10dc\u10d8 "+a+"."},
gii(){return"\u10e4\u10e3\u10da\u10d8\u10e1 \u10e9\u10d0\u10d3\u10d4\u10d1\u10d0"},
gic(){return"\u10d0\u10e0\u10d0, \u10db\u10d0\u10d3\u10da\u10dd\u10d1\u10d0"},
gij(){return"\u10e0\u10d0\u10db\u10d3\u10d4\u10dc\u10d8\u10db\u10d4 \u10d9\u10d5\u10d8\u10e0\u10d0\u10e8\u10d8 \u10de\u10da\u10d0\u10e2\u10e4\u10dd\u10e0\u10db\u10d0 \u10e5\u10e0\u10d4\u10d1\u10d0 \u2013 \u10e4\u10e3\u10da\u10d8 \u10ec\u10d0\u10e1\u10e3\u10da\u10d8\u10d0. \u10db\u10d0\u10e6\u10d0\u10da\u10d8 \u10db\u10dd\u10d2\u10d4\u10d1\u10d0 \u10e0\u10d8\u10e1\u10d9\u10d8\u10e1 \u10d2\u10d0\u10e0\u10d4\u10e8\u10d4 \u10d0\u10e0 \u10d0\u10e0\u10e1\u10d4\u10d1\u10dd\u10d1\u10e1: \u10d4\u10e1 \u10e4\u10d8\u10dc\u10d0\u10dc\u10e1\u10e3\u10e0\u10d8 \u10de\u10d8\u10e0\u10d0\u10db\u10d8\u10d3\u10d0 \u10d8\u10e7\u10dd."},
gie(){return"\u10e1\u10ec\u10dd\u10e0\u10d8\u10d0! \u10d5\u10d8\u10dc\u10ea \u10e0\u10d8\u10e1\u10d9\u10d8\u10e1 \u10d2\u10d0\u10e0\u10d4\u10e8\u10d4 \u10db\u10d0\u10e6\u10d0\u10da \u10db\u10dd\u10d2\u10d4\u10d1\u10d0\u10e1 \u10d2\u10de\u10d8\u10e0\u10d3\u10d4\u10d1\u10d0, \u10db\u10d0\u10e1 \u10e8\u10d4\u10dc\u10d8 \u10e4\u10e3\u10da\u10d8 \u10e3\u10dc\u10d3\u10d0. \u10e0\u10d4\u10d0\u10da\u10e3\u10e0\u10d8 \u10d8\u10dc\u10d5\u10d4\u10e1\u10e2\u10d8\u10ea\u10d8\u10d4\u10d1\u10d8 \u10db\u10d4\u10e0\u10e7\u10d4\u10dd\u10d1\u10e1 \u2013 \u10e0\u10dd\u10d2\u10dd\u10e0\u10ea \u10e8\u10d4\u10dc\u10d8 ETF."},
gju(){return"\u10e8\u10d4\u10ee\u10d5\u10d4\u10d3\u10e0\u10d0 \u10d1\u10d0\u10dc\u10d9\u10d8\u10e1 \u10d9\u10dd\u10dc\u10e1\u10e3\u10da\u10e2\u10d0\u10dc\u10e2\u10d7\u10d0\u10dc"},
gjt(){return"\u10e8\u10d4\u10dc\u10d8 \u10d9\u10dd\u10dc\u10e1\u10e3\u10da\u10e2\u10d0\u10dc\u10e2\u10d8 \u10d2\u10d8\u10e0\u10e9\u10d4\u10d5\u10e1, ETF \u201e\u10e2\u10dd\u10de-\u10e4\u10dd\u10dc\u10d3\u10e8\u10d8\u201c \u10d2\u10d0\u10d3\u10d0\u10d8\u10e2\u10d0\u10dc\u10dd: 5% \u10e8\u10d4\u10e1\u10d5\u10da\u10d8\u10e1 \u10e1\u10d0\u10d9\u10dd\u10db\u10d8\u10e1\u10d8\u10dd \u10d3\u10d0 \u10e7\u10dd\u10d5\u10d4\u10da\u10ec\u10da\u10d8\u10e3\u10e0\u10d0\u10d3 2% \u10ee\u10d0\u10e0\u10ef\u10d8."},
gjv(){return"\u10e4\u10dd\u10dc\u10d3\u10e8\u10d8 \u10d2\u10d0\u10d3\u10d0\u10e2\u10d0\u10dc\u10d0"},
