hZ(a){return"\u0421\u043d\u044f\u0442\u043e: "+a},
gmN(){return"\u041a\u0440\u0435\u0434\u0438\u0442\u044b \u0438 \u0440\u0430\u0441\u0441\u0440\u043e\u0447\u043a\u0438"},
