gqB(){return"\u0418\u0437 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442 \u043d\u0430\u043b\u043e\u0433\u0438 \u0438 \u0432\u0437\u043d\u043e\u0441\u044b \u2014 \u043d\u0430 \u043f\u0435\u043d\u0441\u0438\u044e, \u043c\u0435\u0434\u0438\u0446\u0438\u043d\u0441\u043a\u0443\u044e \u0441\u0442\u0440\u0430\u0445\u043e\u0432\u043a\u0443 \u0438 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u043e. \u041f\u043b\u0430\u043d\u0438\u0440\u0443\u0439 \u0432\u0441\u0435\u0433\u0434\u0430 \u043f\u043e \u0441\u0443\u043c\u043c\u0435 \u043d\u0430 \u0440\u0443\u043a\u0438."},
gqA(){return"\u0412 \u0440\u0430\u0441\u0447\u0451\u0442\u043d\u043e\u043c \u043b\u0438\u0441\u0442\u043a\u0435 \u0432\u0438\u0434\u043d\u043e \u043e\u0431\u0435 \u0441\u0443\u043c\u043c\u044b. \u041d\u0430 \u0440\u0443\u043a\u0438 \u2014 \u044d\u0442\u043e \u0442\u043e, \u0447\u0442\u043e \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u0441\u0447\u0451\u0442."},
gqX(){return"\u0410\u0440\u0435\u043d\u0434\u0430: \u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 \u0442\u0440\u0435\u0442\u0438"},
gqW(){return"\u041f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0443 \u0431\u043e\u043b\u044c\u0448\u043e\u0433\u043e \u043f\u0430\u043b\u044c\u0446\u0430 \u0430\u0440\u0435\u043d\u0434\u0430 \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u0430 \u0441\u0442\u043e\u0438\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435 \u0442\u0440\u0435\u0442\u0438 \u0434\u043e\u0445\u043e\u0434\u0430 \u043d\u0430 \u0440\u0443\u043a\u0438. \u0418\u043d\u0430\u0447\u0435 \u043f\u043e\u0447\u0442\u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043d\u0430 \u0441\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u0438\u044f."},
gqV(){return"\u041f\u0435\u0440\u0435\u0434 \u043f\u0435\u0440\u0435\u0435\u0437\u0434\u043e\u043c \u0441\u043b\u043e\u0436\u0438 \u0432\u0441\u0451: \u0430\u0440\u0435\u043d\u0434\u0443, \u043a\u043e\u043c\u043c\u0443\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u043b\u0430\u0442\u0435\u0436\u0438, \u0441\u0432\u0435\u0442, \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442, \u043c\u0435\u0431\u0435\u043b\u044c \u0438 \u0437\u0430\u043b\u043e\u0433."},
gqt(){return"\u041c\u0430\u0448\u0438\u043d\u0430 \u0441\u0442\u043e\u0438\u0442 \u0434\u043e\u0440\u043e\u0436\u0435 \u0441\u0432\u043e\u0435\u0439 \u0446\u0435\u043d\u044b"},
gqs(){return"\u0421\u0442\u0440\u0430\u0445\u043e\u0432\u043a\u0430, \u0431\u0435\u043d\u0437\u0438\u043d, \u043d\u0430\u043b\u043e\u0433, \u0440\u0435\u043c\u043e\u043d\u0442 \u0438 \u043f\u043e\u0442\u0435\u0440\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043a\u0430\u0436\u0434\u044b\u0439 \u043c\u0435\u0441\u044f\u0446 \u2014 \u0447\u0430\u0441\u0442\u043e \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u043a\u0430\u0436\u0435\u0442\u0441\u044f."},
gqr(){return"\u0427\u0435\u0441\u0442\u043d\u043e \u0441\u0440\u0430\u0432\u043d\u0438 \u0441 \u0432\u0435\u043b\u043e\u0441\u0438\u043f\u0435\u0434\u043e\u043c, \u0430\u0432\u0442\u043e\u0431\u0443\u0441\u043e\u043c \u0438 \u043c\u0435\u0442\u0440\u043e. \u041c\u0430\u0448\u0438\u043d\u0430 \u043e\u043f\u0440\u0430\u0432\u0434\u0430\u043d\u0430, \u0435\u0441\u043b\u0438 \u043e\u043d\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043d\u0443\u0436\u043d\u0430."},
gqO(){return"\u041f\u0435\u0440\u0432\u044b\u0439 \u0432\u0437\u043d\u043e\u0441 \u0438 \u0438\u043f\u043e\u0442\u0435\u043a\u0430"},
gqN(){return"\u0414\u043b\u044f \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u0434\u043e\u043c\u0430 \u043d\u0443\u0436\u043d\u044b \u0441\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u0438\u044f (\u043f\u0435\u0440\u0432\u044b\u0439 \u0432\u0437\u043d\u043e\u0441), \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u0434\u0430\u0451\u0442 \u0432 \u0434\u043e\u043b\u0433 \u0431\u0430\u043d\u043a. \u0427\u0435\u043c \u0431\u043e\u043b\u044c\u0448\u0435 \u043f\u0435\u0440\u0432\u044b\u0439 \u0432\u0437\u043d\u043e\u0441, \u0442\u0435\u043c \u043c\u0435\u043d\u044c\u0448\u0435 \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043e\u0432 \u0442\u044b \u043f\u043b\u0430\u0442\u0438\u0448\u044c."},
gqM(){return"\u0421\u043c\u043e\u0442\u0440\u0438 \u043d\u0430 \u0441\u0442\u0430\u0432\u043a\u0443, \u0441\u0440\u043e\u043a \u0438 \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e\u0435 \u043f\u043e\u0433\u0430\u0448\u0435\u043d\u0438\u0435. \u0417\u0430 25 \u043b\u0435\u0442 \u0434\u0430\u0436\u0435 \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u0430\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u0430 \u0432 \u0441\u0442\u0430\u0432\u043a\u0435 \u0431\u044b\u0441\u0442\u0440\u043e \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0431\u043e\u043b\u044c\u0448\u0438\u0435 \u0434\u0435\u043d\u044c\u0433\u0438."},
gqz(){return"\u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0430\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u0430 \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0443\u0442\u0430!"},
gqy(){return"\u041f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0443 4 % \u0442\u0432\u043e\u0438 \u0432\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u043c\u043e\u0433\u043b\u0438 \u0431\u044b \u043a\u0430\u0436\u0434\u044b\u0439 \u043c\u0435\u0441\u044f\u0446 \u043e\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u0442\u044c \u0432\u0441\u0435 \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u044b\u0435 \u0440\u0430\u0441\u0445\u043e\u0434\u044b. \u0422\u0435\u043f\u0435\u0440\u044c \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e."},
gqx(){return"\u041f\u0440\u0430\u0432\u0438\u043b\u043e 4 %: \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438 \u0442\u0435\u043c, \u043a\u0442\u043e \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u043e \u0441\u043d\u0438\u043c\u0430\u043b \u043e\u043a\u043e\u043b\u043e 4 % \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430, \u0434\u0435\u043d\u0435\u0433 \u043e\u0431\u044b\u0447\u043d\u043e \u0445\u0432\u0430\u0442\u0430\u043b\u043e \u043e\u0447\u0435\u043d\u044c \u043d\u0430\u0434\u043e\u043b\u0433\u043e. \u042d\u0442\u043e \u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043e."},
gmM(){return"\u041e\u0431\u0440\u0430\u0437 \u0436\u0438\u0437\u043d\u0438"},
gmJ(){return"\u0414\u043e\u0441\u0443\u0433, \u043e\u0442\u043f\u0443\u0441\u043a, \u043e\u0434\u0435\u0436\u0434\u0430 \u0438 \u043f\u0440\u043e\u0447\u0435\u0435: \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0442\u044b \u0442\u0440\u0430\u0442\u0438\u0448\u044c \u0438\u0437 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u0438 \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u0438\u0439."},
gmI(){return"\u042d\u043a\u043e\u043d\u043e\u043c\u043d\u044b\u0439"},
