gmG(){return"\u0420\u043e\u0441\u043a\u043e\u0448\u043d\u044b\u0439"},
mH(a,b){return a+" \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0445 \u0434\u0435\u043d\u0435\u0433 \xb7 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435 "+b+" \u0432 \u043c\u0435\u0441\u044f\u0446"},
mL(a){return"\u041f\u0440\u0438 \u043d\u044b\u043d\u0435\u0448\u043d\u0435\u043c \u0434\u043e\u0445\u043e\u0434\u0435 \u043e\u043a\u043e\u043b\u043e "+a+" \u0432 \u043c\u0435\u0441\u044f\u0446"},
gpN(){return"\u0414\u043e\u0441\u0443\u0433 \u0438 \u043e\u0431\u0440\u0430\u0437 \u0436\u0438\u0437\u043d\u0438"},
gpv(){return"\u041f\u043e\u043a\u0430 \u0441\u0447\u0451\u0442 \u0432 \u043c\u0438\u043d\u0443\u0441\u0435, \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043d\u0430\u043a\u043e\u043f\u043b\u0435\u043d\u0438\u044f \u043d\u0430 \u043f\u0430\u0443\u0437\u0435: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0438\u0437\u0431\u0430\u0432\u044c\u0441\u044f \u043e\u0442 \u0434\u043e\u0440\u043e\u0433\u043e\u0433\u043e \u043e\u0432\u0435\u0440\u0434\u0440\u0430\u0444\u0442\u0430."},
gqL(){return"\u0411\u043e\u043b\u044c\u0448\u0435 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u2014 \u0431\u043e\u043b\u044c\u0448\u0435 \u0442\u0440\u0430\u0442?"},
qK(a){return"\u0421 \u0440\u043e\u0441\u0442\u043e\u043c \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u0447\u0430\u0441\u0442\u043e \u0440\u0430\u0441\u0442\u0443\u0442 \u0438 \u0440\u0430\u0441\u0445\u043e\u0434\u044b: \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0430 \u043f\u043e\u0431\u043e\u043b\u044c\u0448\u0435, \u043c\u0430\u0448\u0438\u043d\u0430 \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0435, \u0431\u043e\u043b\u044c\u0448\u0435 \u043e\u0442\u043f\u0443\u0441\u043a\u043e\u0432. \u042d\u0442\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0435\u0439 \u043e\u0431\u0440\u0430\u0437\u0430 \u0436\u0438\u0437\u043d\u0438: \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0448\u044c \u0431\u043e\u043b\u044c\u0448\u0435, \u0430 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043f\u043e\u0447\u0442\u0438 \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435. \u041e\u0431\u0440\u0430\u0437 \u0436\u0438\u0437\u043d\u0438 \u043d\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0432\u043a\u043b\u0430\u0434\u043a\u0435 \xab"+a+"\xbb."},
gqJ(){return"\u041f\u0440\u043e\u0441\u0442\u043e\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e: \u0432\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0439 \u0445\u043e\u0442\u044f \u0431\u044b \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443 \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u0440\u0438\u0431\u0430\u0432\u043a\u0438, \u043f\u043e\u043a\u0430 \u043d\u0435 \u043f\u0440\u0438\u0432\u044b\u043a \u043a \u043d\u043e\u0432\u044b\u043c \u0434\u0435\u043d\u044c\u0433\u0430\u043c. \u0427\u0435\u043c \u043c\u0435\u043d\u044c\u0448\u0435 \u0442\u0435\u0431\u0435 \u043d\u0443\u0436\u043d\u043e \u0434\u043b\u044f \u0436\u0438\u0437\u043d\u0438, \u0442\u0435\u043c \u0440\u0430\u043d\u044c\u0448\u0435 \u0442\u0435\u0431\u044f \u0441\u043c\u043e\u0433\u0443\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0442\u0432\u043e\u0438 \u0432\u043b\u043e\u0436\u0435\u043d\u0438\u044f."},
ka(a){return"\u041f\u0440\u043e\u0434\u0430\u0442\u044c: +"+a},
gkb(){return"\u041c\u0430\u0448\u0438\u043d\u0430 \u043f\u0440\u043e\u0434\u0430\u043d\u0430. \u041c\u0430\u0448\u0438\u043d\u044b \u0431\u044b\u0441\u0442\u0440\u043e \u0434\u0435\u0448\u0435\u0432\u0435\u044e\u0442, \u0430 \u043d\u0435\u043f\u043e\u0433\u0430\u0448\u0435\u043d\u043d\u044b\u0439 \u043a\u0440\u0435\u0434\u0438\u0442 \u0432\u0441\u0451 \u0440\u0430\u0432\u043d\u043e \u043f\u0440\u0438\u0434\u0451\u0442\u0441\u044f \u0432\u044b\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u0442\u044c."},
ru(a){return"\u0418\u0442\u043e\u0433\u0438 \u0433\u043e\u0434\u0430 \xb7 \u0432\u043e\u0437\u0440\u0430\u0441\u0442 "+a},
