gpq(){return"\u0421\u043b\u043e\u043c\u0430\u043b\u0430\u0441\u044c \u0441\u0442\u0438\u0440\u0430\u043b\u044c\u043d\u0430\u044f \u043c\u0430\u0448\u0438\u043d\u0430"},
pp(a){return"\u041d\u043e\u0432\u0430\u044f \u0441\u0442\u043e\u0438\u0442 "+a+". \u0414\u043e\u043b\u0433\u043e \u0431\u0435\u0437 \u043d\u0435\u0451 \u043d\u0435 \u043e\u0431\u043e\u0439\u0442\u0438\u0441\u044c."},
gpr(){return"\u0417\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u0438\u0437 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0439 \u043f\u043e\u0434\u0443\u0448\u043a\u0438"},
gpt(){return"\u041e\u043d\u0430 \u043a\u0430\u043a \u0440\u0430\u0437 \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e."},
gpn(){return"\u041f\u043e\u043f\u0440\u043e\u0431\u043e\u0432\u0430\u0442\u044c \u0434\u0435\u0448\u0451\u0432\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442"},
gpo(){return"\u0414\u0435\u0448\u0435\u0432\u043b\u0435, \u043d\u043e \u043c\u043e\u0436\u0435\u0442 \u043d\u0435 \u043f\u0440\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c\u0441\u044f."},
gpu(){return"\u041e\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u0432 \u0440\u0430\u0441\u0441\u0440\u043e\u0447\u043a\u0443"},
gps(){return"\u0413\u043e\u0442\u043e\u0432\u043e. \u0424\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0430\u044f \u043f\u043e\u0434\u0443\u0448\u043a\u0430 \u0441\u043f\u0430\u0441\u0430\u0435\u0442 \u043e\u0442 \u0434\u043e\u0440\u043e\u0433\u0438\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043e\u0432, \u043a\u043e\u0433\u0434\u0430 \u0447\u0442\u043e-\u0442\u043e \u043b\u043e\u043c\u0430\u0435\u0442\u0441\u044f."},
pf(a,b){return"\u0412\u043d\u0438\u043c\u0430\u043d\u0438\u0435: \u0432 \u0441\u0443\u043c\u043c\u0435 \u0442\u044b \u043f\u043b\u0430\u0442\u0438\u0448\u044c "+a+" \u0432\u043c\u0435\u0441\u0442\u043e "+b+". \u0420\u0430\u0441\u0441\u0440\u043e\u0447\u043a\u0430 \u0432\u0441\u0451 \u0434\u0435\u043b\u0430\u0435\u0442 \u0434\u043e\u0440\u043e\u0436\u0435."},
gkN(){return"\u041e\u0431\u0432\u0430\u043b \u043d\u0430 \u0431\u0438\u0440\u0436\u0435!"},
