gra(){return"\u041a\u0443\u043f\u0438\u0442\u044c \u0432 \u0440\u0430\u0441\u0441\u0440\u043e\u0447\u043a\u0443"},
grb(){return"\u041f\u043e\u0434\u0443\u043c\u0430\u0442\u044c 30 \u0434\u043d\u0435\u0439"},
gre(){return"\u041c\u043d\u0435 \u044d\u0442\u043e \u043f\u0440\u0430\u0432\u0434\u0430 \u043d\u0443\u0436\u043d\u043e?"},
