gqZ(){return"\u0414\u043b\u044f \u0447\u0440\u0435\u0437\u0432\u044b\u0447\u0430\u0439\u043d\u044b\u0445 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0439 \u0438 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0445 \u0446\u0435\u043b\u0435\u0439 \u2014 \u043d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0441\u0447\u0451\u0442: \u0434\u0435\u043d\u044c\u0433\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0432\u0441\u0435\u0433\u0434\u0430. \u0412\u043a\u043b\u0430\u0434 \u0434\u0430\u0451\u0442 \u0447\u0443\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0435, \u043d\u043e \u0434\u0435\u043d\u044c\u0433\u0438 \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u044b \u043d\u0430 \u0441\u0440\u043e\u043a. \u041d\u0430 \u043c\u043d\u043e\u0433\u043e \u043b\u0435\u0442 \u2014 \u0448\u0438\u0440\u043e\u043a\u043e \u0434\u0438\u0432\u0435\u0440\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 ETF: \u043e\u043d \u043a\u043e\u043b\u0435\u0431\u043b\u0435\u0442\u0441\u044f, \u043d\u043e \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 \u0432\u0441\u0435\u0433\u043e."},
gqY(){return"\u041f\u0440\u0430\u0432\u0438\u043b\u043e: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0430\u044f \u043f\u043e\u0434\u0443\u0448\u043a\u0430 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 \u0442\u0440\u0438 \u043c\u0435\u0441\u044f\u0446\u0430 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432, \u043f\u043e\u0442\u043e\u043c \u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0435 \u0432\u043b\u043e\u0436\u0435\u043d\u0438\u044f. \u041f\u0440\u043e\u0446\u0435\u043d\u0442\u044b \u043f\u043e \u043d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u043c\u0443 \u0441\u0447\u0451\u0442\u0443 \u0447\u0430\u0441\u0442\u043e \u043b\u0438\u0448\u044c \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0440\u0430\u0432\u043d\u044b \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438."},
